flt = sys.argv[1] if len(sys.argv) > 1 else ''
shard, nshard = (int(x) for x in os.environ.get('WB_SHARD', '0/1').split('/'))
only = None                                          # WB_LABELS=file: run exactly the mutants whose labels are listed there, one per line
if os.environ.get('WB_LABELS'): only = set(l.strip() for l in open(os.environ['WB_LABELS']) if l.strip())
first = int(os.environ.get('WB_FROM', '0'))        # skip the mutants before this index (re-run only the newest ones)
last = int(os.environ.get('WB_TO', '1000000'))     # ... and those from this index on
survived=[]; killed=0; bad=[]
for idx,(label,f,old,new,tests) in enumerate(M):
    if idx < first or idx >= last or idx % nshard != shard: continue
    if flt and flt not in label and flt not in f: continue
    if only is not None and label not in only: continue
    src=open(f, newline='').read()                     # newline='': keep CRLF files (the user's own files) byte-identical after the restore
    if src.count(old)!=1: bad.append((label, src.count(old))); continue
    open(f,'w',newline='').write(src.replace(old,new))
    try:
        dead=False; note=''
        for t in tests:
            b=subprocess.run(['make','build/'+t],capture_output=True,text=True)
            if b.returncode!=0: note='(does not compile: %s)' % b.stderr.strip().splitlines()[-1][:100] if b.stderr.strip() else '(build failed)'; dead=None; break
            try: r=subprocess.run(['./build/'+t],capture_output=True,text=True,errors='replace',timeout=300)
            except subprocess.TimeoutExpired: dead=True; note='(hang)'; break
            if r.returncode!=0:
                dead=True; n=[l for l in r.stdout.splitlines() if 'FAIL' in l]
                where=n[0].split(':')[0].replace('FAIL','').strip() if n else ''        # "line 148": which check saw it first (to audit a kill by a single check)
                note='%s: %d checks, first at %s' % (t, len(n), where) if n else '%s: crash rc=%d' % (t, r.returncode); break
        if dead is None: bad.append((label, note))
        elif dead: killed+=1; print('killed   %-52s %s' % (label, note), flush=True)
        else: survived.append(label); print('SURVIVED %-52s' % label, flush=True)
    finally:
        open(f,'w',newline='').write(src)
print('\n%d killed, %d survived, %d unusable' % (killed, len(survived), len(bad)))
for s in survived: print('  survived:', s)
for b in bad: print('  unusable:', b)
